fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    let mut ia = 0;
    let mut ib = 0;
    let a_bytes = a.as_bytes();
    let b_bytes = b.as_bytes();
    let alen = a.len();
    let blen = b.len();
    while ia < alen && ib < blen {
        let ca = a_bytes[ia] as char;
        let cb = b_bytes[ib] as char;
        let da = ca.is_ascii_digit();
        let db = cb.is_ascii_digit();
        if da && db {
            let mut ja = ia;
            let mut jb = ib;
            while ja < alen && a_bytes[ja].is_ascii_digit() { ja += 1; }
            while jb < blen && b_bytes[jb].is_ascii_digit() { jb += 1; }
            let anum = &a[ia..ja];
            let bnum = &b[ib..jb];
            // strip leading zeros
            let a_trim = anum.trim_start_matches('0');
            let b_trim = bnum.trim_start_matches('0');
            let a_trim = if a_trim.is_empty() { "0" } else { a_trim };
            let b_trim = if b_trim.is_empty() { "0" } else { b_trim };
            if a_trim.len() != b_trim.len() {
                return a_trim.len().cmp(&b_trim.len());
            }
            if a_trim != b_trim {
                return a_trim.cmp(b_trim);
            }
            // numeric equal, compare original (more zeros smaller? lexical)
            if anum != bnum {
                return anum.cmp(bnum);
            }
            ia = ja;
            ib = jb;
        } else if da != db {
            return (ca as u8).cmp(&(cb as u8));
        } else {
            if ca != cb {
                return (ca as u8).cmp(&(cb as u8));
            }
            ia += 1;
            ib += 1;
        }
    }
    alen.cmp(&blen)
}

#[derive(Debug)]
struct Placeholder {
    group: String, // empty means auto, otherwise numeric string or named
    is_auto: bool,
    padding: Option<usize>,
    raw: String,
}

// Output pattern parsing
fn parse_output_pattern(pattern: &str) -> Result<(Vec<Segment>, Option<String>), String> {
    // Returns segments and error string if padding parse fails
    // Segment: either Escaped char, Literal string, or Placeholder
    let mut segments: Vec<Segment> = Vec::new();
    let mut i = 0;
    let chars: Vec<char> = pattern.chars().collect();
    let n = chars.len();
    let mut auto_counter = 0usize;
    while i < n {
        if chars[i] == '\\' && i + 1 < n && (chars[i+1] == '{' || chars[i+1] == '}') {
            // escaped brace
            let ch = chars[i+1];
            // push as literal
            if let Some(Segment::Literal(s)) = segments.last_mut() {
                s.push(ch);
            } else {
                segments.push(Segment::Literal(ch.to_string()));
            }
            i += 2;
        } else if chars[i] == '{' {
            // find closing }
            let mut j = i+1;
            let mut found = None;
            while j < n {
                if chars[j] == '\\' && j+1<n && (chars[j+1]=='{' || chars[j+1]=='}') {
                    j+=2;
                    continue;
                }
                if chars[j] == '}' {
                    found = Some(j);
                    break;
                }
                j+=1;
            }
            if let Some(end) = found {
                // inside braces
                let inner = pattern[i+1..end].to_string(); // but we have_chars indices, need char slice
                // Actually reconstruct inner string properly with char indices maybe multi-byte? Use chars slice
                let inner_chars: String = chars[i+1..end].iter().collect();
                // Parse inner as G:P
                // Split by ':' if present
                let (g_part, p_part) = if let Some(colon_pos) = inner_chars.find(':') {
                    let (gp, pp) = inner_chars.split_at(colon_pos);
                    (gp, Some(pp[1..].to_string()))
                } else {
                    (inner_chars.as_str(), None)
                };
                let g_str = g_part.to_string();
                let is_auto = g_str.is_empty();
                let group = if is_auto {
                    auto_counter += 1;
                    auto_counter.to_string()
                } else {
                    g_str.clone()
                };
                // parse padding
                let padding = if let Some(pstr) = p_part {
                    if pstr.is_empty() {
                        None
                    } else {
                        match pstr.parse::<usize>() {
                            Ok(v) => Some(v),
                            Err(_) => {
                                return Err(format!("error: [output-format] unable to parse padding of '{}'", pstr));
                            }
                        }
                    }
                } else {
                    None
                };
                // placeholder
                segments.push(Segment::Placeholder { group, is_auto, padding, orig_group: g_str });
                i = end + 1;
            } else {
                // no closing, treat as literal
                if let Some(Segment::Literal(s)) = segments.last_mut() {
                    s.push('{');
                } else {
                    segments.push(Segment::Literal("{".to_string()));
                }
                i += 1;
            }
        } else if chars[i] == '}' {
            // stray } with no opening, but if escaped previously handled.
            // If not escaped, treat as literal ?
            // However escaping handles \} earlier. So here literal }
            if let Some(Segment::Literal(s)) = segments.last_mut() {
                s.push('}');
            } else {
                segments.push(Segment::Literal("}".to_string()));
            }
            i+=1;
        } else {
            // literal run until next special
            let mut lit = String::new();
            while i < n {
                if chars[i]=='\\' && i+1<n && (chars[i+1]=='{' || chars[i+1]=='}') {
                    break;
                }
                if chars[i]=='{' || chars[i]=='}' {
                    break;
                }
                lit.push(chars[i]);
                i+=1;
            }
            if !lit.is_empty() {
                if let Some(Segment::Literal(s)) = segments.last_mut() {
                    s.push_str(&lit);
                } else {
                    segments.push(Segment::Literal(lit));
                }
            } else {
                // to avoid infinite loop, advance if not handled? But lit empty means special char ahead, will be handled in next iteration
                // If we broke due to special without consuming, loop will handle it
                // To avoid infinite loop, ensure we don't stall: if lit empty, we will handle special next loop, so nothing to do
                // But to prevent infinite when n==i and special char is } or { already handled above, we already handled. So here only when next char is \+brace, we break and will handle escaped case next iteration.
                // So continue.
                continue;
            }
        }
    }
    Ok((segments, None))
}

#[derive(Debug, Clone)]
enum Segment {
    Literal(String),
    Placeholder { group: String, is_auto: bool, padding: Option<usize>, orig_group: String },
}

fn is_numeric(s: &str) -> bool {
    if s.is_empty() { return false; }
    let mut chars = s.chars();
    let first = chars.next().unwrap();
    let rest = if first=='-' { chars.as_str() } else { s };
    if rest.is_empty() { return false; }
    rest.chars().all(|c| c.is_ascii_digit())
}

fn is_positive_number(s: &str) -> bool {
    if s.is_empty() { return false; }
    if s.starts_with('-') { return false; }
    s.chars().all(|c| c.is_ascii_digit())
}

fn apply_padding(value: &str, padding: Option<usize>) -> String {
    if let Some(p) = padding {
        if is_positive_number(value) {
            if value.len() < p {
                let zeros = "0".repeat(p - value.len());
                return format!("{}{}", zeros, value);
            }
        }
        value.to_string()
    } else {
        value.to_string()
    }
}

fn evaluate_segments(segments: &[Segment], caps: &Option<Captures>, enumerator: Option<usize>) -> String {
    let mut out = String::new();
    for seg in segments {
        match seg {
            Segment::Literal(s) => out.push_str(s),
            Segment::Placeholder { group, is_auto: _, padding, orig_group: _ } => {
                let value = if group == "0" {
                    // whole match - caps[0]
                    if let Some(c) = caps {
                        c.get_0.clone()
                    } else {
                        String::new()
                    }
                } else if let Ok(idx) = group.parse::<usize>() {
                    if idx == 0 {
                        // handled above
                        String::new()
                    } else {
                        // numeric group: for sort mode, enumerator maps to idx 1, others empty
                        // for regex mode, numeric caps
                        if let Some(c) = caps {
                            // regex mode has caps map includes numeric
                            c.get_by_name_or_index(group).unwrap_or_default()
                        } else {
                            // sort mode: enumerator is idx 1
                            if idx == 1 {
                                if let Some(n) = enumerator {
                                    n.to_string()
                                } else {
                                    String::new()
                                }
                            } else {
                                String::new()
                            }
                        }
                    }
                } else {
                    // named group
                    if let Some(c) = caps {
                        c.get_by_name_or_index(group).unwrap_or_default()
                    } else {
                        String::new()
                    }
                };
                let padded = apply_padding(&value, *padding);
                out.push_str(&padded);
            }
        }
    }
    out
}

#[derive(Debug, Clone)]
struct Captures {
    get_0: String,
    // map from group name or index string to value
    map: HashMap<String, String>,
}

impl Captures {
    fn get_by_name_or_index(&self, key: &str) -> Option<String> {
        self.map.get(key).cloned()
    }
}

fn build_command() -> Command {
    let mut cmd = Command::new("executable")
        .version("1.6.4")
        .about("Batch rename utility for developers")
        .after_help("OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("dir").short('d').long("dir").value_name("PATH").help("Sets the working directory"))
        .arg(Arg::new("depth").long("depth").value_name("DEPTH").help("Optional value to overwrite inferred subdirectory depth value in 'regex' mode"))
        .arg(Arg::new("no-extension").short('E').long("no-extension").help("Does not preserve the extension of input files in 'sort' and 'regex' options").action(ArgAction::SetTrue))
        .arg(Arg::new("generate").short('g').long("generate").value_name("PATH").help("Stores a JSON map file in '<PATH>' after renaming files"))
        .arg(Arg::new("help").short('h').long("help").help("Print help (see a summary with '-h')").action(ArgAction::Help))
        .arg(Arg::new("help-long").long("help").help("Print help").action(ArgAction::Help))
        .arg(Arg::new("mkdir").short('k').long("mkdir").help("Recursively creates all parent directories of '<OUTPUT>' if they are missing").action(ArgAction::SetTrue))
        .arg(Arg::new("map").short('m').long("map").value_name("PATH").help("Sets the path of map file to be used for renaming files").alias("from-file"))
        .arg(Arg::new("max-depth").long("max-depth").value_name("DEPTH").help("Optional value to set the maximum of subdirectory depth value in 'regex' mode"))
        .arg(Arg::new("quiet").short('q').long("quiet").help("Does not print the map table to stdout").action(ArgAction::SetTrue))
        .arg(Arg::new("regex").short('r').long("regex").value_name("PATTERN").help("Regex pattern to match by filenames"))
        .arg(Arg::new("sort").short('s').long("sort").value_name("ORDER").help("Sets the order of natural sorting (by name) to rename files using enumerator").value_parser(["asc","desc"]))
        .arg(Arg::new("test").short('t').long("test").help("Runs in test mode without renaming actual files").alias("dry-run").action(ArgAction::SetTrue))
        .arg(Arg::new("version").short('V').long("version").help("Print version").action(ArgAction::Version))
        .arg(Arg::new("overwrite").short('w').long("overwrite").help("Overwrites output files, otherwise, a '_' is prepended to filename").action(ArgAction::SetTrue))
        .arg(Arg::new("positional").value_name("[SOURCE] OUTPUT").help("OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option").num_args(0..));
    // We need to handle help flags manually: we have both -h and --help as help actions, but we need to distinguish -h vs --help for output length.
    // Use Command's default help handling: but we added two help args? Simpler: add one help flag with short -h and long --help, but we need to differentiate output for -h vs --help.
    // Actual binary shows -h prints short help, --help prints long help. clap does that automatically when help is defined with action Help.
    // So we should define single help arg with both short and long.
    // Instead we override later manually.
    cmd
}

fn print_help(short: bool) {
    if short {
        // corresponds to -h
        println!("Batch rename utility for developers\n");
        println!("Usage: executable [OPTIONS] [[SOURCE] OUTPUT]...\n");
        println!("Arguments:");
        println!("  [[SOURCE] OUTPUT]...  OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option\n");
        println!("Options:");
        println!("  -d, --dir <PATH>         Sets the working directory");
        println!("      --depth <DEPTH>      Optional value to overwrite inferred subdirectory depth value in 'regex' mode");
        println!("  -E, --no-extension       Does not preserve the extension of input files in 'sort' and 'regex' options");
        println!("  -g, --generate <PATH>    Stores a JSON map file in '<PATH>' after renaming files");
        println!("  -h, --help               Print help (see more with '--help')");
        println!("  -k, --mkdir              Recursively creates all parent directories of '<OUTPUT>' if they are missing");
        println!("  -m, --map <PATH>         Sets the path of map file to be used for renaming files [aliases: --from-file]");
        println!("      --max-depth <DEPTH>  Optional value to set the maximum of subdirectory depth value in 'regex' mode");
        println!("  -q, --quiet              Does not print the map table to stdout");
        println!("  -r, --regex <PATTERN>    Regex pattern to match by filenames");
        println!("  -s, --sort <ORDER>       Sets the order of natural sorting (by name) to rename files using enumerator [possible values: asc, desc]");
        println!("  -t, --test               Runs in test mode without renaming actual files [aliases: --dry-run]");
        println!("  -V, --version            Print version");
        println!("  -w, --overwrite          Overwrites output files, otherwise, a '_' is prepended to filename");
        println!("\nOUTPUT pattern accepts placeholders that have the format of '{{G:P}}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.");
    } else {
        println!("Batch rename utility for developers\n");
        println!("Usage: executable [OPTIONS] [[SOURCE] OUTPUT]...\n");
        println!("Arguments:");
        println!("  [[SOURCE] OUTPUT]...");
        println!("          OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option\n");
        println!("Options:");
