fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    let a_bytes = a.as_bytes();
    let b_bytes = b.as_bytes();
    let mut ia = 0usize;
    let mut ib = 0usize;
    let alen = a.len();
    let blen = b.len();
    while ia < alen && ib < blen {
        let ca = a_bytes[ia] as char;
        let cb = b_bytes[ib] as char;
        let da = ca.is_ascii_digit();
        let db = cb.is_ascii_digit();
        if da && db {
            let mut ja = ia;
            let mut jb = ib;
            while ja < alen && a_bytes[ja].is_ascii_digit() { ja += 1; }
            while jb < blen && b_bytes[jb].is_ascii_digit() { jb += 1; }
            let anum = &a[ia..ja];
            let bnum = &b[ib..jb];
            let a_trim = anum.trim_start_matches('0');
            let b_trim = bnum.trim_start_matches('0');
            let a_trim = if a_trim.is_empty() { "0" } else { a_trim };
            let b_trim = if b_trim.is_empty() { "0" } else { b_trim };
            if a_trim.len() != b_trim.len() {
                return a_trim.len().cmp(&b_trim.len());
            }
            if a_trim != b_trim {
                return a_trim.cmp(b_trim);
            }
            if anum != bnum {
                return anum.cmp(bnum);
            }
            ia = ja;
            ib = jb;
        } else if da != db {
            return (ca as u8).cmp(&(cb as u8));
        } else {
            if ca != cb {
                return (ca as u8).cmp(&(cb as u8));
            }
            ia += 1;
            ib += 1;
        }
    }
    alen.cmp(&blen)
}

#[derive(Debug, Clone)]
enum Segment {
    Literal(String),
    Placeholder { group: String, padding: Option<usize> },
}

fn parse_output_pattern(pattern: &str) -> Result<Vec<Segment>, String> {
    let mut segments: Vec<Segment> = Vec::new();
    let chars: Vec<char> = pattern.chars().collect();
    let n = chars.len();
    let mut i = 0usize;
    let mut auto_counter = 0usize;
    while i < n {
        if chars[i] == '\\' && i + 1 < n && (chars[i+1] == '{' || chars[i+1] == '}') {
            let ch = chars[i+1];
            match segments.last_mut() {
                Some(Segment::Literal(s)) => s.push(ch),
                _ => segments.push(Segment::Literal(ch.to_string())),
            }
            i += 2;
        } else if chars[i] == '{' {
            // find closing }
            let mut j = i + 1;
            let mut found = None;
            while j < n {
                if chars[j] == '\\' && j + 1 < n && (chars[j+1] == '{' || chars[j+1] == '}') {
                    j += 2;
                    continue;
                }
                if chars[j] == '}' {
                    found = Some(j);
                    break;
                }
                j += 1;
            }
            if let Some(end) = found {
                // inner content
                let inner: String = chars[i+1..end].iter().collect();
                let (g_part, p_part) = if let Some(colon) = inner.find(':') {
                    let (a,b) = inner.split_at(colon);
                    (a.to_string(), Some(b[1..].to_string()))
                } else {
                    (inner.clone(), None)
                };
                let is_auto = g_part.is_empty();
                let group = if is_auto {
                    auto_counter += 1;
                    auto_counter.to_string()
                } else {
                    g_part.clone()
                };
                let padding = if let Some(pstr) = p_part {
                    if pstr.is_empty() {
                        None
                    } else {
                        match pstr.parse::<usize>() {
                            Ok(v) => Some(v),
                            Err(_) => {
                                return Err(format!("error: [output-format] unable to parse padding of '{}'", pstr));
                            }
                        }
                    }
                } else {
                    None
                };
                segments.push(Segment::Placeholder { group, padding });
                i = end + 1;
            } else {
                // no closing, treat as literal
                match segments.last_mut() {
                    Some(Segment::Literal(s)) => s.push('{'),
                    _ => segments.push(Segment::Literal("{".to_string())),
                }
                i += 1;
            }
        } else if chars[i] == '}' {
            match segments.last_mut() {
                Some(Segment::Literal(s)) => s.push('}'),
                _ => segments.push(Segment::Literal("}".to_string())),
            }
            i += 1;
        } else {
            // literal run
            let mut lit = String::new();
            while i < n {
                if chars[i] == '\\' && i + 1 < n && (chars[i+1] == '{' || chars[i+1] == '}') {
                    break;
                }
                if chars[i] == '{' || chars[i] == '}' {
                    break;
                }
                lit.push(chars[i]);
                i += 1;
            }
            if !lit.is_empty() {
                match segments.last_mut() {
                    Some(Segment::Literal(s)) => s.push_str(&lit),
                    _ => segments.push(Segment::Literal(lit)),
                }
            } else {
                // shouldn't happen, but to avoid infinite loop
                i += 1;
            }
        }
    }
    Ok(segments)
}

fn is_positive_number(s: &str) -> bool {
    if s.is_empty() { return false; }
    if s.starts_with('-') { return false; }
    s.chars().all(|c| c.is_ascii_digit())
}

fn apply_padding(value: &str, padding: Option<usize>) -> String {
    if let Some(p) = padding {
        if is_positive_number(value) && value.len() < p {
            let zeros = "0".repeat(p - value.len());
            return format!("{}{}", zeros, value);
        }
    }
    value.to_string()
}

#[derive(Debug, Clone)]
struct Captures {
    whole: String,
    map: HashMap<String, String>,
}

impl Captures {
    fn get(&self, key: &str) -> Option<String> {
        self.map.get(key).cloned()
    }
}

fn evaluate_segments(segments: &[Segment], caps: Option<&Captures>, enumerator: Option<usize>) -> String {
    let mut out = String::new();
    for seg in segments {
        match seg {
            Segment::Literal(s) => out.push_str(s),
            Segment::Placeholder { group, padding } => {
                let value = if group == "0" {
                    if let Some(c) = caps {
                        c.whole.clone()
                    } else {
                        // for sort mode, {0} is filename
                        // enumerator mode: {0} should be filename, but we handle separately
                        // This case will be handled via enumerator? Actually for sort, caps is None, group "0" should be filename
                        // We'll need filename to be passed via caps? For sort we will pass caps with whole = filename
                        // So this branch will be taken with caps Some
                        String::new()
                    }
                } else if let Ok(idx) = group.parse::<usize>() {
                    if idx == 0 {
                        String::new()
                    } else {
                        if let Some(c) = caps {
                            // regex mode
                            c.get(group).unwrap_or_default()
                        } else {
                            // sort mode: only group 1 is enumerator
                            if idx == 1 {
                                if let Some(n) = enumerator {
                                    n.to_string()
                                } else {
                                    String::new()
                                }
                            } else {
                                String::new()
                            }
                        }
                    }
                } else {
                    // named
                    if let Some(c) = caps {
                        c.get(group).unwrap_or_default()
                    } else {
                        String::new()
                    }
                };
                let padded = apply_padding(&value, *padding);
                out.push_str(&padded);
            }
        }
    }
    out
}

fn get_extension(path: &str) -> String {
    // path is relative path like "a.txt" or "subdir/file.tar.gz" or "a" or ".hidden"
    // extension is after last '.' in basename
    let basename = path.rsplit('/').next().unwrap_or(path);
    if let Some(pos) = basename.rfind('.') {
        if pos == 0 {
            // leading dot, check if there is another dot after
            // For ".hidden.txt", pos is at last dot (position of . before txt), not 0, so will be >0
            // For ".hidden", pos 0 => no extension
            String::new()
        } else {
            basename[pos..].to_string()
        }
    } else {
        String::new()
    }
}

