    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    // Help/version handling before clap
    let mut has_short_help = false;
    let mut has_long_help = false;
    let mut has_version = false;
    for a in &args[1..] {
        if a == "-h" {
            has_short_help = true;
        } else if a == "--help" {
            has_long_help = true;
        } else if a == "-V" || a == "--version" {
            has_version = true;
        } else if a.starts_with('-') && !a.starts_with("--") && a.len() > 1 {
            // combined short flags
            if a.contains('h') {
                has_short_help = true;
            }
            if a.contains('V') {
                has_version = true;
            }
        }
        // also handle --help with =? not needed
    }
    if has_version {
        println!("nomino 1.6.4");
        process::exit(0);
    }
    if has_long_help {
        print_help(false);
        process::exit(0);
    }
    if has_short_help {
        print_help(true);
        process::exit(0);
    }

    let mut cmd = Command::new("executable")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("dir").short('d').long("dir").value_name("PATH").help("Sets the working directory"))
        .arg(Arg::new("depth").long("depth").value_name("DEPTH").value_parser(clap::value_parser!(usize)).help("Optional value to overwrite inferred subdirectory depth value in 'regex' mode"))
        .arg(Arg::new("no-extension").short('E').long("no-extension").help("Does not preserve the extension of input files in 'sort' and 'regex' options").action(ArgAction::SetTrue))
        .arg(Arg::new("generate").short('g').long("generate").value_name("PATH").help("Stores a JSON map file in '<PATH>' after renaming files"))
        .arg(Arg::new("mkdir").short('k').long("mkdir").help("Recursively creates all parent directories of '<OUTPUT>' if they are missing").action(ArgAction::SetTrue))
        .arg(Arg::new("map").short('m').long("map").value_name("PATH").help("Sets the path of map file to be used for renaming files").alias("from-file"))
        .arg(Arg::new("max-depth").long("max-depth").value_name("DEPTH").value_parser(clap::value_parser!(usize)).help("Optional value to set the maximum of subdirectory depth value in 'regex' mode"))
        .arg(Arg::new("quiet").short('q').long("quiet").help("Does not print the map table to stdout").action(ArgAction::SetTrue))
        .arg(Arg::new("regex").short('r').long("regex").value_name("PATTERN").help("Regex pattern to match by filenames"))
        .arg(Arg::new("sort").short('s').long("sort").value_name("ORDER").value_parser(["asc","desc"]).help("Sets the order of natural sorting (by name) to rename files using enumerator"))
        .arg(Arg::new("test").short('t').long("test").help("Runs in test mode without renaming actual files").alias("dry-run").action(ArgAction::SetTrue))
        .arg(Arg::new("overwrite").short('w').long("overwrite").help("Overwrites output files, otherwise, a '_' is prepended to filename").action(ArgAction::SetTrue))
        .arg(Arg::new("positional").value_name("[SOURCE] OUTPUT").help("OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option").num_args(0..));

    let matches = match cmd.try_get_matches_from(args.clone()) {
        Ok(m) => m,
        Err(e) => {
            e.exit();
        }
    };

    let dir_opt = matches.get_one::<String>("dir").cloned();
    let depth_opt = matches.get_one::<usize>("depth").cloned();
    let max_depth_opt = matches.get_one::<usize>("max-depth").cloned();
    let no_ext = matches.get_flag("no-extension");
    let generate_opt = matches.get_one::<String>("generate").cloned();
    let mkdir_flag = matches.get_flag("mkdir");
    let map_opt = matches.get_one::<String>("map").cloned();
    let quiet = matches.get_flag("quiet");
    let regex_opt = matches.get_one::<String>("regex").cloned();
    let sort_opt = matches.get_one::<String>("sort").cloned();
    let test_flag = matches.get_flag("test");
    let overwrite_flag = matches.get_flag("overwrite");
    let positional: Vec<String> = matches.get_many::<String>("positional").map(|v| v.cloned().collect()).unwrap_or_default();

    let has_sort = sort_opt.is_some();
    let has_regex_flag = regex_opt.is_some();
    let has_map_flag = map_opt.is_some();

    // Check for positional with flags error: optional SOURCE must be used without setting regex, map or sort flags
    if positional.len() >= 2 && (has_sort || has_regex_flag || has_map_flag) {
        eprintln!("error: optional SOURCE must be used without setting regex, map or sort flags");
        process::exit(1);
    }

    // Determine work_dir
    let work_dir = if let Some(d) = dir_opt {
        PathBuf::from(d)
    } else {
        env::current_dir().unwrap()
    };
    if !work_dir.exists() || !work_dir.is_dir() {
        eprintln!("error: No such file or directory (os error 2)");
        process::exit(1);
    }

    // Validate map file
    if let Some(ref map_path) = map_opt {
        let p = Path::new(map_path);
        if !p.exists() {
            eprintln!("error: No such file or directory (os error 2)");
            process::exit(1);
        }
        if p.is_dir() {
            eprintln!("error: Is a directory (os error 21)");
            process::exit(1);
        }
        let content = match fs::read_to_string(p) {
            Ok(c) => c,
            Err(e) => {
                if e.kind() == std::io::ErrorKind::IsADirectory {
                    eprintln!("error: Is a directory (os error 21)");
                } else {
                    eprintln!("error: No such file or directory (os error 2)");
                }
                process::exit(1);
            }
        };
        match serde_json::from_str::<Value>(&content) {
            Ok(_) => {},
            Err(e) => {
                eprintln!("error: {}", e);
                process::exit(1);
            }
        }
    }

    // Validate generate path
    if let Some(ref gen_path) = generate_opt {
        let p = Path::new(gen_path);
        if p.exists() && p.is_dir() {
            eprintln!("error: Is a directory (os error 21)");
            process::exit(1);
        }
        if let Some(parent) = p.parent() {
            if !parent.as_os_str().is_empty() && !parent.exists() {
                eprintln!("error: No such file or directory (os error 2)");
                process::exit(1);
            }
        }
    }

    // Determine effective regex and output
    let mut effective_regex: Option<String> = None;
    let mut effective_output: Option<String> = None;
    let mut effective_sort: Option<String> = sort_opt.clone();

    if has_sort || has_regex_flag || has_map_flag {
        // flag mode
        if positional.len() == 1 {
            effective_output = Some(positional[0].clone());
            effective_regex = regex_opt.clone();
            // effective_sort already set
        } else if positional.len() == 0 {
            effective_regex = regex_opt.clone();
            // effective_sort already
            // check required output for sort/regex
            if has_sort {
                // sort requires output formatter, regardless of map
                eprintln!("error: [output-format] output formatter must be set");
                process::exit(1);
            }
            if has_regex_flag {
                // Need to generate clap missing required error
                // Build a command that requires positional
                let mut err_cmd = Command::new("executable")
                    .disable_help_flag(true)
                    .disable_version_flag(true)
                    .arg(Arg::new("dir").short('d').long("dir").value_name("PATH"))
                    .arg(Arg::new("depth").long("depth").value_name("DEPTH").value_parser(clap::value_parser!(usize)))
                    .arg(Arg::new("no-extension").short('E').long("no-extension").action(ArgAction::SetTrue))
                    .arg(Arg::new("generate").short('g').long("generate").value_name("PATH"))
                    .arg(Arg::new("mkdir").short('k').long("mkdir").action(ArgAction::SetTrue))
                    .arg(Arg::new("map").short('m').long("map").value_name("PATH").alias("from-file"))
                    .arg(Arg::new("max-depth").long("max-depth").value_name("DEPTH").value_parser(clap::value_parser!(usize)))
                    .arg(Arg::new("quiet").short('q').long("quiet").action(ArgAction::SetTrue))
                    .arg(Arg::new("regex").short('r').long("regex").value_name("PATTERN"))
                    .arg(Arg::new("sort").short('s').long("sort").value_name("ORDER").value_parser(["asc","desc"]))
                    .arg(Arg::new("test").short('t').long("test").alias("dry-run").action(ArgAction::SetTrue))
                    .arg(Arg::new("overwrite").short('w').long("overwrite").action(ArgAction::SetTrue))
                    .arg(Arg::new("positional").value_name("[SOURCE] OUTPUT").required(true).num_args(0..));
                let mut fake_args = vec!["executable".to_string()];
                for a in &args[1..] {
                    fake_args.push(a.clone());
                }
                match err_cmd.try_get_matches_from(fake_args) {
                    Ok(_) => {},
                    Err(e) => e.exit(),
                }
            }
            // if only map flag and no sort/regex, no output required, proceed
        } else {
            // len >=2 already errored, but just in case
        }
    } else {
        // no flags, positional determines regex mode
        if positional.len() >= 2 {
            effective_regex = Some(positional[positional.len()-2].clone());
            effective_output = Some(positional[positional.len()-1].clone());
        } else if positional.len() == 0 || positional.len() == 1 {
            eprintln!("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '/workspace/executable --help' for more information.");
            process::exit(1);
        }
    }

    // Check for sort without output after handling positional len 1 case already, but also need to handle case where sort present and effective_output is None (when map also present? but we already handled sort requires output)
    // For safety, if has_sort and effective_output is None {
    //   eprintln!("[output-format] output formatter must be set");
    //   exit 1
    // }

    // Determine mode precedence: regex > sort > map
    let is_regex_mode = effective_regex.is_some();
    let is_sort_mode = !is_regex_mode && effective_sort.is_some();
    let is_map_mode = has_map_flag && !is_regex_mode && !is_sort_mode;

    // Parse output pattern if needed
    let output_segments: Option<Vec<Segment>> = if let Some(ref out_pat) = effective_output {
        match parse_output_pattern(out_pat) {
            Ok(segs) => Some(segs),
            Err(msg) => {
                eprintln!("{}", msg);
                process::exit(1);
            }
        }
    } else {
        None
    };

    // Validate regex pattern syntax if regex mode
    let regex_compiled: Option<Regex> = if let Some(ref pat) = effective_regex {
        match Regex::new(pat) {
            Ok(r) => Some(r),
            Err(e) => {
                eprintln!("error: {}", e);
                process::exit(1);
            }
        }
    } else {
        None
    };

    // If map mode, handle map logic and exit
    if is_map_mode {
        let map_path = map_opt.unwrap();
        let content = fs::read_to_string(&map_path).unwrap();
        let map_val: Value = serde_json::from_str(&content).unwrap();
        let obj = map_val.as_object().unwrap();
        let mut entries: Vec<(String,String)> = Vec::new();
        for (k,v) in obj {
            let out_str = v.as_str().unwrap_or("").to_string();
            entries.push((k.clone(), out_str));
        }
        // Sort entries by Output natural ascending for processing? For table, final sorted by Output
        // For collision handling, we need to process in Output sorted order? Let's sort by Output natural ascending for processing
        entries.sort_by(|a,b| natural_cmp(&a.1, &b.1));

        // For --test mode, we need to handle dedup? But map internal duplicate outputs: if duplicate outputs, dedup?
        // For map, if two inputs map to same output, that's duplicate output. In --test, deduplicate to last? Let's treat similarly.
        // We'll implement resolve for map as well.

        let final_entries = resolve_map_entries(entries, &work_dir, test_flag, overwrite_flag);

        // Print table if not quiet and not empty
        if !quiet && !final_entries.is_empty() {
            print_table(&final_entries);
        }

        // Handle generate
        if let Some(ref gen_path) = generate_opt {
            let mut map_to_write = BTreeMap::new();
            for (inp, out) in &final_entries {
                map_to_write.insert(out.clone(), inp.clone());
            }
            let json_str = serde_json::to_string_pretty(&map_to_write).unwrap();
            if let Err(e) = fs::write(gen_path, json_str + "\n") {
                if e.kind() == std::io::ErrorKind::IsADirectory {
                    eprintln!("error: Is a directory (os error 21)");
                    process::exit(1);
                } else {
                    eprintln!("error: No such file or directory (os error 2)");
                    process::exit(1);
                }
            }
        }

        // Perform renames if not test
        if !test_flag {
            let mut any_error = false;
            // For map, rename order should be table order (Output ascending) to handle swap correctly?
            // We'll rename in final_entries order (Output ascending)
            for (inp, out) in &final_entries {
                let src = work_dir.join(inp);
                let dst = work_dir.join(out);
                // Check parent
                if let Some(parent) = dst.parent() {
                    if !parent.exists() {
                        if mkdir_flag {
                            if let Err(_) = fs::create_dir_all(parent) {
                                eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                                any_error = true;
                                continue;
                            }
                        } else {
                            eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                            any_error = true;
                            continue;
                        }
                    }
                }
                // Check source exists
                if !src.exists() {
                    eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                    any_error = true;
                    continue;
                }
                // If overwrite false and dst exists (and not same as src), we already handled via resolve to avoid, but if still exists due to not resolved, need to handle?
                // We'll just attempt rename; if overwrite false and dst exists, our resolve should have made it unique, so not happen.
                if let Err(e) = fs::rename(&src, &dst) {
                    // Check if error is due to overwrite? For now print generic
                    eprintln!("[error] unable to rename '{}': {} (os error 2)", inp, e);
                    any_error = true;
                }
            }
            if any_error {
                process::exit(1);
            }
        }
        process::exit(0);
    }

    // Sort mode handling
    if is_sort_mode {
        let sort_order = effective_sort.unwrap();
        let out_segs = output_segments.unwrap();
        // collect top-level entries
        let mut inputs: Vec<String> = Vec::new();
        let read = fs::read_dir(&work_dir).unwrap();
        for entry in read {
            let entry = entry.unwrap();
            let fname = entry.file_name().to_string_lossy().to_string();
            // Skip . and .. not needed
            inputs.push(fname);
        }
        // sort natural
        if sort_order == "asc" {
            inputs.sort_by(|a,b| natural_cmp(a,b));
        } else {
            inputs.sort_by(|a,b| natural_cmp(b,a));
        }

        let mut initial_entries: Vec<(String,String)> = Vec::new();
        for (idx, inp) in inputs.iter().enumerate() {
            let enumerator = idx + 1;
            // For sort, caps is filename as whole
            let mut map = HashMap::new();
            map.insert("0".to_string(), inp.clone());
            let caps = Captures { whole: inp.clone(), map: map.clone() };
            // Also need to insert enumerator as group 1? For placeholder evaluation, group 1 will be enumerator via enumerator param
            // We'll pass enumerator separately
            let out_str = evaluate_segments(&out_segs, Some(&caps), Some(enumerator));
            let mut final_out = out_str;
            // extension handling
            if !no_ext {
                let ext = get_extension(inp);
                if !ext.is_empty() {
                    final_out.push_str(&ext);
                }
            }
            initial_entries.push((inp.clone(), final_out));
        }

        // Resolve collisions
        let final_entries = if test_flag {
            resolve_sort_regex_test(&initial_entries, &work_dir, overwrite_flag)
        } else {
            resolve_sort_regex_real(&initial_entries, &work_dir, overwrite_flag)
        };

        // Print table sorted by Output ascending? For sort mode, we observed table sorted by Output ascending (which for distinct outputs corresponds to Input ascending). We'll sort final entries by Output natural ascending for display
        let mut display_entries = final_entries.clone();
        display_entries.sort_by(|a,b| natural_cmp(&a.1, &b.1));

        if !quiet && !display_entries.is_empty() {
            print_table(&display_entries);
        }

        // Generate
        if let Some(ref gen_path) = generate_opt {
            let mut map_to_write = BTreeMap::new();
            for (inp, out) in &final_entries {
                map_to_write.insert(out.clone(), inp.clone());
            }
            let json_str = serde_json::to_string_pretty(&map_to_write).unwrap();
            if let Err(e) = fs::write(gen_path, json_str + "\n") {
                if e.kind() == std::io::ErrorKind::IsADirectory {
                    eprintln!("error: Is a directory (os error 21)");
                    process::exit(1);
                } else {
                    eprintln!("error: No such file or directory (os error 2)");
                    process::exit(1);
                }
            }
        }

        // Rename if not test
        if !test_flag {
            let mut any_error = false;
            // For rename order, use display order (Output ascending) to handle swaps correctly as earlier deduced?
            // Use display order
            for (inp, out) in &display_entries {
                let src = work_dir.join(inp);
                let dst = work_dir.join(out);
                if let Some(parent) = dst.parent() {
                    if !parent.exists() {
                        if mkdir_flag {
                            let _ = fs::create_dir_all(parent);
                        } else {
                            eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                            any_error = true;
                            continue;
                        }
                    }
                }
                if !src.exists() {
                    eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                    any_error = true;
                    continue;
                }
                if let Err(e) = fs::rename(&src, &dst) {
                    eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                    any_error = true;
                }
            }
            if any_error {
                process::exit(1);
            }
        }
        process::exit(0);
    }

    // Regex mode
    if is_regex_mode {
        let pattern = effective_regex.unwrap();
        let out_segs = output_segments.unwrap();
        let regex = regex_compiled.unwrap();

        // depth logic
        let inferred = pattern.matches('/').count() + 1;
        let (lo, hi) = if depth_opt.is_some() && max_depth_opt.is_some() {
            let d = depth_opt.unwrap();
            let m = max_depth_opt.unwrap();
            (std::cmp::min(d, m), m)
        } else if depth_opt.is_some() {
            let d = depth_opt.unwrap();
            (d, d)
        } else if max_depth_opt.is_some() {
            let m = max_depth_opt.unwrap();
            if m == 0 {
                (0, 0)
            } else {
                if m < inferred {
                    // empty range
                    (1, 0) // lo > hi => empty
                } else {
                    (inferred, m)
                }
            }
        } else {
            (inferred, inferred)
        };

        let mut candidates: Vec<String> = Vec::new();
        if lo <= hi {
            // include depth 0 candidate "" if 0 in range
            if lo <= 0 && 0 <= hi {
                candidates.push("".to_string());
            }
            // walk directory up to hi
            if hi >= 1 {
                let mut walker = walkdir::WalkDir::new(&work_dir).min_depth(1).max_depth(hi).follow_links(false).into_iter();
                for entry in walker {
                    let entry = match entry {
                        Ok(e) => e,
                        Err(_) => continue,
                    };
                    let path = entry.path();
                    let rel = path.strip_prefix(&work_dir).unwrap().to_string_lossy().replace("\\", "/");
                    // compute depth
                    let depth = if rel.is_empty() { 0 } else { rel.matches('/').count() + 1 };
                    if depth < lo || depth > hi {
                        continue;
                    }
                    candidates.push(rel);
                }
            }
        }

        // filter by regex match and collect captures
        let mut initial_entries: Vec<(String,String)> = Vec::new();
        // For regex, sorting of candidates for processing: lexicographic ascending
        candidates.sort_by(|a,b| a.cmp(b));

        for cand in candidates {
            if let Some(caps) = regex.captures(&cand) {
                // Build Captures struct
                let whole = caps.get(0).map(|m| m.as_str().to_string()).unwrap_or_default();
                let mut map = HashMap::new();
                map.insert("0".to_string(), whole.clone());
                for i in 1..caps.len() {
                    if let Some(m) = caps.get(i) {
                        map.insert(i.to_string(), m.as_str().to_string());
                    } else {
                        map.insert(i.to_string(), "".to_string());
                    }
                }
                // named groups
                for name in regex.capture_names().flatten() {
                    if let Some(m) = caps.name(name) {
                        map.insert(name.to_string(), m.as_str().to_string());
                    }
                }
                let cap_struct = Captures { whole: whole.clone(), map };
                let mut out_str = evaluate_segments(&out_segs, Some(&cap_struct), None);
                if !no_ext {
                    let ext = get_extension(&cand);
                    if !ext.is_empty() {
                        out_str.push_str(&ext);
                    }
                }
                initial_entries.push((cand.clone(), out_str));
            }
        }

        // For regex, initial_entries are already sorted by cand lexicographic, but we should sort by Input lexicographic for processing
        // Already sorted.

        let final_entries = if test_flag {
            resolve_sort_regex_test(&initial_entries, &work_dir, overwrite_flag)
        } else {
            resolve_sort_regex_real(&initial_entries, &work_dir, overwrite_flag)
        };

        let mut display_entries = final_entries.clone();
        display_entries.sort_by(|a,b| natural_cmp(&a.1, &b.1));

        if !quiet && !display_entries.is_empty() {
            print_table(&display_entries);
        }

        if let Some(ref gen_path) = generate_opt {
            let mut map_to_write = BTreeMap::new();
            for (inp, out) in &final_entries {
                map_to_write.insert(out.clone(), inp.clone());
            }
            let json_str = serde_json::to_string_pretty(&map_to_write).unwrap();
            if let Err(e) = fs::write(gen_path, json_str + "\n") {
                if e.kind() == std::io::ErrorKind::IsADirectory {
                    eprintln!("error: Is a directory (os error 21)");
                    process::exit(1);
                } else {
                    eprintln!("error: No such file or directory (os error 2)");
                    process::exit(1);
                }
            }
        }

        if !test_flag {
            let mut any_error = false;
            for (inp, out) in &display_entries {
                let src = if inp.is_empty() {
                    work_dir.clone()
                } else {
                    work_dir.join(inp)
                };
                let dst = work_dir.join(out);
                if let Some(parent) = dst.parent() {
                    if !parent.exists() {
                        if mkdir_flag {
                            let _ = fs::create_dir_all(parent);
                        } else {
                            eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                            any_error = true;
                            continue;
                        }
                    }
                }
                if inp.is_empty() {
                    // renaming work_dir itself? Skip?
                    eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                    any_error = true;
                    continue;
                }
                if !src.exists() {
                    eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                    any_error = true;
                    continue;
                }
                if let Err(_) = fs::rename(&src, &dst) {
                    eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", inp);
                    any_error = true;
                }
            }
            if any_error {
                process::exit(1);
            }
        }
        process::exit(0);
    }

    // If reached here, no mode matched
    eprintln!("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '/workspace/executable --help' for more information.");
    process::exit(1);
}

fn resolve_sort_regex_test(entries: &Vec<(String,String)>, work_dir: &Path, overwrite: bool) -> Vec<(String,String)> {
    // For --test, internal collisions deduplicate to last, external collisions underscore
    // Group by output
