    // For each output, keep last input in original order (which is sorted input order)
    // To keep last, we need to know original order: entries is sorted by Input, so last in group is last occurrence
    for (out, inputs) in grouped {
        let last_input = inputs.last().unwrap().clone();
        deduped.push((last_input, out));
    }
    // Now handle external collisions for deduped entries
    // Need to sort deduped by Input order? For external handling, we need processing order. Use Input sorted order? For now sort by Input natural/lexicographic? But deduped order input sorted? We'll sort deduped by Input natural/lexicographic for processing, but final display will be sorted by Output.
    deduped.sort_by(|a,b| a.0.cmp(&b.0));
    let mut final_entries: Vec<(String,String)> = Vec::new();
    let mut assigned: HashSet<String> = HashSet::new();
    for (inp, out) in deduped {
        let mut cur_out = out.clone();
        if !overwrite {
            // check external existence and also assigned outputs
            loop {
                let exists = work_dir.join(&cur_out).exists();
                let collides_assigned = assigned.contains(&cur_out);
