fn print_table(entries: &Vec<(String,String)>) {
    if entries.is_empty() {
        return;
    }
    let mut max_in = "Input".len();
    let mut max_out = "Output".len();
    for (inp, out) in entries {
        if inp.len() > max_in { max_in = inp.len(); }
        if out.len() > max_out { max_out = out.len(); }
    }
    let border = format!("+{}+{}+", "-".repeat(max_in+2), "-".repeat(max_out+2));
    println!("{}", border);
    println!("| {:<width_in$} | {:<width_out$} |", "Input", "Output", width_in=max_in, width_out=max_out);
    println!("{}", border);
    for (inp, out) in entries {
        println!("| {:<width_in$} | {:<width_out$} |", inp, out, width_in=max_in, width_out=max_out);
    }
    println!("{}", border);
}
